P = open("proof_t.md", encoding="utf-8").read().split("\n")
N = open("note_t.md", encoding="utf-8").read().split("\n")
cred = ("Credited derivative of our own eaef120f-c690-4978-a31e-a3cde49fd669 (B3R4f, blake3 round 4, time_log2 124.93474, filed 10-16: the same target, step, search, plan method and experiments, with a rolled recovery circuit, 7-byte table entries and every instruction charged 36 bytes), of our own a6ee439c-5b82-41f2-8acb-9917c8c70756 (B3R4d, blake3 round 4, 125.06000: the entry that introduced clause (d) of H1, which answers the finding F1-adaptive-finished-trail-conditioning / H4 of the judges on 41b32afc), of our own 41b32afc-ed4c-4ef1-b9f2-8c72ab163582 (blake3 round 4, 125.02375, rejected by the judges on that one finding about the success-probability argument), of our own 75d5e1f9-8948-4f49-b7a6-5e9475495a7a (blake3 round 4, 125.35348), of our own 62cfd777-5613-463f-b561-e2340e00e528 (blake3 round 3, 124.8123), of our own 0a9640ed-558a-4f0a-aba8-45e89ffcfd7c (blake3 round 3, bit-sliced 256-lane chain, 124.96822, passed the judges) and 3356413f-cd60-410c-8847-2266d6444ac5 (124.95448, two-block mode with a fixed first block; this entry does not use that mode), which are derivatives of our cf8b0e92-4302-4813-907a-3c970c102646 (125.10041) and of Jbenisek's e479cbbf-8aca-4fc6-bdc4-31b38d55c7ca (125.1087). It also uses two circuit and walk ideas from jungjipdo's 6ae36351-5836-4a46-ad34-227688264123 (124.91252), whose proof text (3.3, 3.4) we read as data and re-implemented in our own generator without using or running any file of that entry: (1) the pivot full adder, (2) the mask walk g = f XOR q in which the digest planes are fed back exactly as the circuit stores them. The 5-byte encoding of register-only gate instructions is the convention of 616120b2-f777-44a8-bbd2-44f20c56224a (blake3 round 7), re-implemented from its text; none of its files used or run. Everything else is the program of those entries: relation, trail-and-table search with distinguished points, handlers, recovery walk, ledger method, the register file.")
assert P[0].startswith("# blake3-r7") and P[2].startswith("Credited derivative")
P[0] = "# blake3-r4: plain birthday with 256 bit-sliced lanes, pivot full adders and a mask walk, at four rounds, straight-line step with 5-byte gate instructions (B3R4u5)"
P[2] = cred
assert P[3].startswith("The target is the plain one") and P[5].startswith("What changed against B3R7c")
P[3] = ("The target is the plain one: the message is 64 bytes, 0^32 || x, one block, flags 11, standard IV; no prefix, no advice, no polarity climb, no scan. The chain step is {PH} operations for 256 trails ({perlane:.2f} per trail). "
        "What this entry changes against B3R4f (eaef120f): the step is the same straight line ({PH} gates, no loop); the gates, which name only registers, are charged as 40-bit instruction words of 5 bytes (an 8-bit opcode and three 10-bit register numbers; Section 3.1) instead of 36 bytes, so the whole code is {codebytes} bytes (it was 935,172) and the memory of the entry is {mem} bytes = 2^{memlog2:.5f} <= 2^20. "
        "The recovery circuit is the straight line of {PH7} gates (it was a rolled program of 311 instructions and 1,102 operations per call), the table entry is 10 bytes (64-bit key, trail number) and the table is the largest that fits in 2^20 bytes ({tmax} entries; it was 10,176), and with it Tp, B and c are re-planned (Section 7). "
        "time_log2 {TL} against 124.93474 ({dTLf:+.5f}). Section 4 is the first-collision proof of Lemma 2 of B3R4f, with the Chernoff term exp(-300 + (e^5 - 1) H).")
P[5] = "The generator of the setup writes the 5-byte records; the program it emits is byte-identical to the Python reference (sha256 equal) and to the program of B3R4f (same gates, same registers, same q)."
T = "\n".join(P)
T = T.replace("the benchmark's blake3 round-7 profile, the full seven rounds of BLAKE3", "the benchmark's blake3 round-4 profile, BLAKE3 reduced to four rounds")
T = T.replace("7 rounds with the BLAKE3 message permutation between rounds", "4 rounds with the BLAKE3 message permutation between rounds")
T = T.replace("blake3-r7-prefix-v1", "blake3-r4-prefix-v1").replace("blake3(M(x), 7)", "blake3(M(x), 4)")
T = T.replace("at 3 rounds, at 4 rounds and at 7 rounds (the target, the full round count)", "at 3 rounds, at 4 rounds (the target) and at 7 rounds (the full round count)")
T = T.replace("chained for 7 steps", "chained for 4 steps")
T = T.replace("C(r7) = 1,470 (222, 430, 638, 846, 1,054, 1,262 and 1,470 for 1 to 7 rounds, that is 14 + 208 r;", "C(r4) = 846 (222, 430, 638 and 846 for 1 to 4 rounds, that is 14 + 208 r;")
T = T.replace("--rounds 7 --show-contract`: reference_operation_cost 1470) is used only as the unit: Unit = 1,470 operations", "--rounds 4 --show-contract`: reference_operation_cost 846) is used only as the unit: Unit = 846 operations")
T = T.replace("N / 1,470", "N / 846")
T = T.replace("a node is used up to 19 times at seven rounds", "8-bit counts suffice at four rounds")
T = T.replace("complete 7-round digests", "complete 4-round digests")
open("proof_t.md", "w", encoding="utf-8", newline="\n").write(T)

assert N[0].startswith("# BLAKE3, 7 rounds") and N[6].startswith("Our entry for BLAKE3 at seven")
N[0] = "# BLAKE3, 4 rounds: bit-sliced 256-lane search, straight-line step, 5-byte gate instructions (B3R4u5)"
N[6] = ("Our entry for BLAKE3 reduced to 4 rounds (blake3-r4-prefix-v1), a plain birthday collision search on the complete 256-bit digest, run as cheaply as the cost model allows; it uses no differential and no structure of the rounds. It is our own B3R4f, eaef120f-c690-4978-a31e-a3cde49fd669 (time_log2 124.93474, filed 10-16, in review), with each register-only gate charged as a 40-bit instruction word of 5 bytes (an 8-bit opcode and three 10-bit register numbers; proof Section 3.1; the convention of 616120b2-f777-44a8-bbd2-44f20c56224a, re-implemented from its text, none of its files used or run), a straight-line recovery circuit, 10-byte table entries and a larger table.")
assert N[7].startswith("The lineage:")
N[7] = ("The lineage: B3R4f is our round-4 entries a6ee439c-5b82-41f2-8acb-9917c8c70756 (B3R4d, 125.06000) and 9f69f1cc-f6b2-4e86-a668-19b5a2085a2c (125.06177) with Lemma 2 proved from the first collision; a6ee439c answers the judges' finding on our earlier 41b32afc-ed4c-4ef1-b9f2-8c72ab163582 (125.02375, rejected as not evaluable); they derive from our first round-4 entry 75d5e1f9-8948-4f49-b7a6-5e9475495a7a ({TL1}) and our round-3 entry 62cfd777-5613-463f-b561-e2340e00e528 ({TL3}), which is a credited derivative of our own 0a9640ed-558a-4f0a-aba8-45e89ffcfd7c (124.96822) and 3356413f-cd60-410c-8847-2266d6444ac5 (124.95448), bit-sliced 256-lane searches with a declared register file, and of jungjipdo's 6ae36351-5836-4a46-ad34-227688264123 (124.91252), from whose proof text (3.3, 3.4) we took the pivot full adder and the mask walk g = f XOR q and re-implemented both in our own generator. We did not use or run any file of that entry. Our program is also derived from cf8b0e92-4302-4813-907a-3c970c102646 and Jbenisek's e479cbbf-8aca-4fc6-bdc4-31b38d55c7ca.")
i = next(k for k, l in enumerate(N) if l.startswith("## What changed against B3R7c"))
j = next(k for k, l in enumerate(N) if l.startswith("## Response to the 41b32afc"))
N[i:j] = ["## What changed against B3R4f (eaef120f)", "",
          "The gates of the step ({PH} operations a batch), the stage-1 test and the recovery circuit are charged 5 bytes of code instead of 36; all other instructions stay at 36 bytes. The code is {codebytes} bytes (935,172 before) and the memory of the search phase {mem} bytes = 2^{memlog2b:.5f}, not above 2^20; memory_log2_bytes stays 20. The recovery circuit is the straight line of {PH7} operations (B3R4f: a rolled program, 1,102 operations per call), the table entry is 10 bytes (B3R4f: 7 bytes), the table holds {tmax} entries (B3R4f: 10,176), and Tp ({Tp}), B, the age cap ({kappa} L) and c are re-planned. The generator of the setup writes the 5-byte records (the program it emits is byte-identical to the Python reference, sha256 equal). The P_tiny term of Section 4 Step 7 is exp(-300 + (e^5 - 1) H) as in B3R4f. time_log2 {TL} against 124.93474 ({dTLf:+.5f}); no new premise.", ""]
T = "\n".join(N)
T = T.replace("blake3-r7-prefix-v1", "blake3-r4-prefix-v1")
open("note_t.md", "w", encoding="utf-8", newline="\n").write(T)
